        var byDate = String(b.createdAt || '').localeCompare(String(a.createdAt || ''));
        if (byDate !== 0) return byDate;
        return (a.attemptIndex || 0) - (b.attemptIndex || 0);
    });
    return { rows: rows, attemptRows: attemptRows };
}

