        }
    }

    if (!samples.length) return null;
    var finalSample = samples[samples.length - 1];
    var faSources = {};
    samples.forEach(function(sample) {
        if (sample.source) faSources[sample.source] = true;
    });
    var faSourceKeys = Object.keys(faSources).sort();
