        if (resumeMatch) {
            resumeDetected = true;
            feedbackLoopCount += 1;
            resumeStages.push((resumeMatch[1] || 'resume') + ' ' + resumeMatch[2] + '/' + resumeMatch[3]);
        } else if (line.indexOf('--resume') !== -1 || line.indexOf('run-agent.sh --continue') !== -1) {
