        cachedTokens: attempt.cachedTokens || 0,
        reasoningTokens: attempt.reasoningTokens || 0,
        rawTokensLine: attempt.rawTokensLine || '',
        source: attempt.source || '',
        url: firstDefined(run.html_url, run.htmlUrl, '')
    };
}

